// Devuelve la configuracion que necesitan los nodos siguientes:
// - lat / lon / ciudad: para personalizar Open-Meteo, Sunrise-Sunset y el prompt del LLM.
// - tono: estilo del briefing (divulgativo).
// - hoy: fecha actual en formato YYYY-MM-DD para la URL de NeoWs.
return [{
  json: {
    lat: 37.608,
    lon: -0.987,
    ciudad: 'Cartagena, España',
    tono: 'divulgativo',
    hoy: new Date().toISOString().slice(0, 10)
  }
}];

// Junta los datos de las 8 fuentes y los deja preparados para el LLM.
// Cada bloque va dentro de try/catch porque las HTTP llevan onError: continueRegularOutput,
// asi que si una API cae, su entrada llega vacia y aqui se ignora sin romper el resto.
const ubic = $('2. Configuración').first().json;
const getJson = (nodo) => { try { return $(nodo).first().json || {}; } catch(e) { return {}; } };

const apodR = getJson('3. NASA APOD');
const issR = getJson('4. Where-ISS');
const neoR = getJson('5. NASA NeoWs (asteroides)');
const launchR = getJson('6. Launch Library 2 (lanzamientos)');
const meteoR = getJson('7. Open-Meteo (nubes nocturnas)');
const sunR = getJson('8. Sunrise-Sunset (crepúsculo)');
const arxivXml = (getJson('9. arXiv astro-ph RSS').data) || getJson('9. arXiv astro-ph RSS');
const spaceXml = (getJson('10. SpaceNews RSS').data) || getJson('10. SpaceNews RSS');

// APOD - imagen astronomica del dia
const apod = {
  titulo: apodR.title || 'Sin título',
  fecha: apodR.date || ubic.hoy,
  url: apodR.url || '',
  explicacion: (apodR.explanation || '').slice(0, 400)
};

// ISS + distancia a la ciudad del usuario (haversine)
const iss = {
  lat: typeof issR.latitude === 'number' ? issR.latitude : 0,
  lon: typeof issR.longitude === 'number' ? issR.longitude : 0,
  altitud_km: Math.round(issR.altitude || 0),
  api_ok: typeof issR.latitude === 'number'
};
const toRad = d => d * Math.PI / 180;
const dLat = toRad(iss.lat - ubic.lat);
const dLon = toRad(iss.lon - ubic.lon);
const hav = Math.sin(dLat/2)**2 + Math.cos(toRad(ubic.lat)) * Math.cos(toRad(iss.lat)) * Math.sin(dLon/2)**2;
iss.distancia_a_ti_km = iss.api_ok ? Math.round(6371 * 2 * Math.atan2(Math.sqrt(hav), Math.sqrt(1-hav))) : null;
iss.sobre_zona = iss.api_ok && iss.distancia_a_ti_km !== null && iss.distancia_a_ti_km < 2000;

// NASA NeoWs - asteroides cercanos hoy
const asteroides = [];
try {
  const dia = (neoR.near_earth_objects && neoR.near_earth_objects[ubic.hoy]) || [];
  dia.slice(0, 3).forEach(a => {
    const ca = (a.close_approach_data && a.close_approach_data[0]) || {};
    const dia_min = (a.estimated_diameter && a.estimated_diameter.meters && a.estimated_diameter.meters.estimated_diameter_min) || 0;
    const dia_max = (a.estimated_diameter && a.estimated_diameter.meters && a.estimated_diameter.meters.estimated_diameter_max) || 0;
    asteroides.push({
      nombre: a.name,
      diametro_m: Math.round((dia_min + dia_max) / 2),
      distancia_lunar: ca.miss_distance ? parseFloat(ca.miss_distance.lunar || 0).toFixed(2) : null,
      velocidad_kmh: ca.relative_velocity ? Math.round(parseFloat(ca.relative_velocity.kilometers_per_hour || 0)) : null,
      peligroso: !!a.is_potentially_hazardous_asteroid
    });
  });
} catch (e) {}

// Launch Library 2 - proximos lanzamientos
const lanzamientos = [];
try {
  (launchR.results || []).slice(0, 3).forEach(l => {
    lanzamientos.push({
      nombre: l.name,
      fecha: (l.net || '').slice(0, 16).replace('T', ' '),
      lugar: (l.pad && l.pad.location && l.pad.location.name) || (l.pad && l.pad.name) || '?',
      cohete: (l.rocket && l.rocket.configuration && l.rocket.configuration.name) || '?',
      status: (l.status && l.status.name) || '?'
    });
  });
} catch (e) {}

// Open-Meteo - nubosidad media de 21h a 03h
let nubes = null;
try {
  const cc = (meteoR.hourly && meteoR.hourly.cloud_cover) || [];
  const horas = (meteoR.hourly && meteoR.hourly.time) || [];
  const nocturnos = [];
  horas.forEach((h, i) => {
    const hora = parseInt(h.slice(11, 13), 10);
    if (hora >= 21 || hora <= 3) nocturnos.push(cc[i]);
  });
  if (nocturnos.length) {
    const avg = Math.round(nocturnos.reduce((a, b) => a + b, 0) / nocturnos.length);
    nubes = {
      cobertura_pct: avg,
      cielo: avg < 25 ? 'despejado' : avg < 60 ? 'parcialmente nublado' : 'cubierto',
      buena_observacion: avg < 40
    };
  }
} catch (e) {}

// Sunrise-Sunset - crepusculo astronomico
let luz = null;
try {
  const r = sunR.results || {};
  const fmt = iso => iso ? iso.slice(11, 16) : '?';
  luz = {
    amanecer: fmt(r.sunrise),
    atardecer: fmt(r.sunset),
    crepusculo_astro_inicio: fmt(r.astronomical_twilight_end),
    duracion_dia_horas: r.day_length ? Math.round(r.day_length / 360) / 10 : null
  };
} catch (e) {}

// Parser RSS muy simple, solo extrae el campo title de cada item
function parseRss(xml, maxItems) {
  if (!xml || typeof xml !== 'string') return [];
  const items = [];
  const re = /<item[^>]*>([\s\S]*?)<\/item>/g;
  let m; let c = 0;
  while ((m = re.exec(xml)) && c < maxItems) {
    const b = m[1];
    const tit = (b.match(/<title[^>]*>(?:<!\[CDATA\[)?([\s\S]*?)(?:\]\]>)?<\/title>/) || [,''])[1].trim();
    if (tit) items.push({ titulo: tit });
    c++;
  }
  return items;
}

const arxiv = parseRss(arxivXml, 6);
const space = parseRss(spaceXml, 5);

const titulos = [
  ...arxiv.map(i => 'PAPER: ' + i.titulo),
  ...space.map(i => 'NOTICIA: ' + i.titulo),
  ...lanzamientos.map(l => 'LANZAMIENTO: ' + l.nombre + ' (' + l.cohete + ')'),
  ...asteroides.map(a => 'ASTEROIDE: ' + a.nombre + ' a ' + a.distancia_lunar + ' distancias lunares')
];

return [{
  json: { ubic, apod, iss, asteroides, lanzamientos, nubes, luz, arxiv, space, titulos }
}];

// Clustering greedy por similitud coseno + construccion del prompt para el LLM.
const embRes = $input.first().json;
const d = $('11. Consolidar datos').first().json;

const embs = embRes.embeddings || [];

function cos(a, b) {
  if (!a.length || !b.length) return 0;
  let dot=0, na=0, nb=0;
  for (let i=0; i<a.length; i++) { dot+=a[i]*b[i]; na+=a[i]*a[i]; nb+=b[i]*b[i]; }
  return dot / (Math.sqrt(na) * Math.sqrt(nb));
}

const UMBRAL = 0.70;
const clusters = [];
for (let i=0; i<d.titulos.length; i++) {
  if (!embs[i]) continue;
  let asignado = false;
  for (const c of clusters) {
    if (cos(embs[i], c.centroide) > UMBRAL) {
      c.items.push(d.titulos[i]);
      for (let j=0; j<c.centroide.length; j++) {
        c.centroide[j] = (c.centroide[j] * (c.items.length - 1) + embs[i][j]) / c.items.length;
      }
      asignado = true;
      break;
    }
  }
  if (!asignado) clusters.push({ centroide: [...embs[i]], items: [d.titulos[i]] });
}

const instrucciones = 'Explica de forma clara y accesible, para público aficionado a la ciencia.';

let grupos = 'Grupos temáticos detectados por clustering semántico:';
clusters.slice(0, 5).forEach((c, i) => {
  grupos += `\nGrupo ${i+1} (${c.items.length} ítems):`;
  c.items.slice(0, 3).forEach(t => grupos += `\n - ${t}`);
});

let bloqueAsteroides = '';
if (d.asteroides.length) {
  bloqueAsteroides = '\n\nAsteroides cercanos hoy (NASA NeoWs):';
  d.asteroides.forEach(a => {
    bloqueAsteroides += `\n - ${a.nombre}: ~${a.diametro_m} m, a ${a.distancia_lunar} distancias lunares` + (a.peligroso ? ' (catalogado como potencialmente peligroso)' : '');
  });
}

let bloqueLanzamientos = '';
if (d.lanzamientos.length) {
  bloqueLanzamientos = '\n\nPróximos lanzamientos espaciales:';
  d.lanzamientos.forEach(l => {
    bloqueLanzamientos += `\n - ${l.nombre} (${l.cohete}) — ${l.fecha} desde ${l.lugar}`;
  });
}

let bloqueCielo = '';
if (d.nubes || d.luz) {
  bloqueCielo = '\n\nCondiciones para observación esta noche en ' + d.ubic.ciudad + ':';
  if (d.nubes) bloqueCielo += `\n - Nubosidad media nocturna: ${d.nubes.cobertura_pct}% (${d.nubes.cielo})`;
  if (d.luz) bloqueCielo += `\n - Atardecer ${d.luz.atardecer}, oscuridad astronómica desde ${d.luz.crepusculo_astro_inicio}`;
  if (d.nubes && d.nubes.buena_observacion) bloqueCielo += '\n - Cielo favorable para observación astronómica';
}

let bloqueIss = '';
if (d.iss.api_ok) {
  bloqueIss = `\n\nEstación Espacial Internacional (ISS) ahora mismo:\n - Latitud ${d.iss.lat.toFixed(2)}, longitud ${d.iss.lon.toFixed(2)}\n - Altitud: ${d.iss.altitud_km} km\n - Distancia desde ${d.ubic.ciudad}: ${d.iss.distancia_a_ti_km.toLocaleString()} km` + (d.iss.sobre_zona ? ' (sobrevolando tu zona)' : '');
} else {
  bloqueIss = '\n\n(Datos de la ISS no disponibles ahora mismo.)';
}

const prompt = `Eres un asistente de ciencia y espacio. Hablas en castellano a un usuario en ${d.ubic.ciudad}.\n\nTONO: ${instrucciones}\n\nREGLAS ESTRICTAS:\n- Usa SOLO los datos que te paso abajo. NO inventes organizaciones, sitios, nombres ni cifras.\n- La ISS es un satélite, no un observatorio en tierra.\n- No uses emojis ni asteriscos ni markdown. Texto plano.\n- Máximo 9 frases.\n- Cubre: imagen del día, ISS, asteroides si los hay, lanzamientos si los hay, condiciones del cielo, 1-2 noticias o papers destacados.\n\nDATOS REALES DE HOY:\n\nImagen astronómica del día (NASA APOD): "${d.apod.titulo}" (${d.apod.fecha})\nDescripción: ${d.apod.explicacion}${bloqueIss}${bloqueAsteroides}${bloqueLanzamientos}${bloqueCielo}\n\n${grupos}\n\nEstructura: saludo breve, imagen del día (cita el título exacto), dónde está la ISS, asteroide o lanzamiento destacado, condiciones del cielo, 1-2 noticias o papers, cierre corto.`;

return [{
  json: {
    prompt,
    ciudad: d.ubic.ciudad,
    apod: d.apod,
    iss: d.iss,
    asteroides: d.asteroides,
    lanzamientos: d.lanzamientos,
    nubes: d.nubes,
    luz: d.luz,
    arxiv: d.arxiv,
    space: d.space,
    num_titulos: d.titulos.length,
    num_grupos: clusters.length,
    embedding_dim: embs[0] ? embs[0].length : 0
  }
}];
